"""Athanor tuning-regression verifier (generated by ``athanor evals capture tuning``).

Runs the self-modification experiment (selfmod or TSP family) for the config in ``config.json`` on the
fixed seeds in the protected ``case.json`` with the *installed* Athanor, prints
one ``ATHANOR_EVAL_METRICS {...}`` line and checks every limit.

Exit 0: every limit holds.  Exit 1: a limit is violated.  Exit 3: error.
"""
import hashlib, json, math, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))


def _num(v):
    return math.inf if v is None or v == "inf" else float(v)


def _clean(v):
    if isinstance(v, float) and not math.isfinite(v):
        return "inf" if v > 0 else "-inf"
    return v


def main():
    try:
        case = json.load(open(os.path.join(HERE, "case.json"), encoding="utf-8"))
        cand = json.load(open(os.path.join(HERE, "config.json"), encoding="utf-8"))
        arm, cfg = dict(cand["arm"]), dict(cand["cfg"])
        workers = int(os.environ.get("ATHANOR_EVAL_WORKERS", "0")) or None
        if case.get("family") == "tsp":   # 3.0: self-modifying TSP solver (athanor.selfmod.tsp_experiment)
            from athanor.selfmod.tsp_experiment import run_tsp_arms
            res = run_tsp_arms(list(case["seeds"]), {"eval": {**arm, "cfg": cfg}}, {"steps": int(case["steps"])},
                               workers=workers or 8)
        else:
            from athanor.selfmod.arms import run_arms
            cfg["steps"] = int(case["steps"])
            res = run_arms(list(case["seeds"]), {"eval": arm}, cfg, workers=workers)
        summary = {k: _clean(v) for k, v in res["summary"]["eval"].items()}
    except Exception as exc:  # infrastructure error, not a reproduced failure
        print(f"ERROR: {type(exc).__name__}: {exc}")
        return 3
    keys = sorted(case.get("fingerprint_metrics") or summary)
    tracked = {k: summary.get(k) for k in keys}
    fp = hashlib.sha256(json.dumps(tracked, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    violations = []
    for lim in case["limits"]:
        v, op, bound = _num(summary.get(lim["metric"])), lim["op"], float(lim["value"])
        ok = {"<=": v <= bound, "<": v < bound, ">=": v >= bound, ">": v > bound}[op]
        if not ok:
            violations.append(f"{lim['metric']}={summary.get(lim['metric'])} violates {op} {lim['value']}")
    print("ATHANOR_EVAL_METRICS " + json.dumps({"metrics": tracked, "fingerprint": fp,
                                                 "violations": violations}, sort_keys=True))
    if violations:
        print("FAIL: " + "; ".join(violations))
        return 1
    print("PASS: all limits hold")
    return 0


if __name__ == "__main__":
    sys.exit(main())
